-- 059: saved drafts of the Create Event form.
--
-- The form autosaves here (and to the browser) so an organiser who refreshes,
-- loses their tab, gets signed out or switches device can carry on where they
-- stopped. `data` is the raw form state (text fields only; images stay in the
-- browser that picked them). The id is generated by the browser so the same
-- draft can be written before and after a reload. Deleted on submit.
--
-- Idempotent: safe to re-run.

BEGIN;

CREATE TABLE IF NOT EXISTS event_drafts (
  id            UUID        PRIMARY KEY,
  organizer_id  UUID        NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name          TEXT        NOT NULL DEFAULT '',
  data          JSONB       NOT NULL DEFAULT '{}'::jsonb,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS event_drafts_organizer_idx ON event_drafts (organizer_id, updated_at DESC);

-- Server-only table (service role); no client access.
ALTER TABLE event_drafts ENABLE ROW LEVEL SECURITY;

COMMIT;
